def project(user: User, fields: Set[String]): Either[String, Json] =
  user.asJson.asObject match {
    case None => Left("resource is not a JSON object")
    case Some(obj) =>
      val unknown = fields -- obj.keys.toSet
      if (unknown.nonEmpty) Left(s"unknown fields: ${unknown.mkString(",")}")
      else Right(Json.fromJsonObject(
        JsonObject.fromIterable(obj.toIterable.filter { case (k, _) => fields(k) })))
  }

